INSERT INTO public.audit_event VALUES
	('2eb5d13e-82e4-43e9-a2f7-a8fdeef07c51', 'CREATED', 'CONTROL_DEFINITION', '1869f531-bf1e-400e-9df9-e315cf2b1912', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "ACCESS-02_SIC", "active": false, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('a6678dd9-8ba6-4ef4-a33f-8d33bc6332b5', 'CREATED', 'CONTROL_DEFINITION_VERSION', '7b54e82a-db84-4f7d-8827-a63aef179628', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "RUN", "itProcess": "MANAGE_ACCESS", "objective": "Activities performed by IT members with privileged accesses must be reviewed :\n- For GxP regulated digital solution, the review of activities must be covered as applicable by the audit trail review\n- For SOX & CSRD regulated digital solution, activities of IT accounts with extended rights (e.g. Firefighters, Privileged accounts) which can have impacts on SOX/CSRD data must be reviewed and documented at least annually.", "ownerTeam": "CYBER_SECURITY", "statement": "Activities Review for privileged accesses", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "1869f531-bf1e-400e-9df9-e315cf2b1912", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "1. GQCMS-QU-STD-0000452-User Access Management Controls: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/867621\n2. DFC-QU-STD-0000298-Access Control: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/581828\n3. DIG-CO-SOP-0015241-SAP Security Baseline: https://opella-connect.veevavault.com/ui/#permalink=V190000000JN001\n4. DFC-QU-SOP-0087024-Business Application Access Management: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/738198", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "* Audit trail review record/report for GxP-regulated digital solutions, covering activities performed under privileged access\n* Documented review log for SOX/CSRD-regulated solutions, covering extended-rights accounts (e.g. Firefighter, Privileged accounts), performed and evidenced at least annually* Reviewer sign-off/approval confirming the review was completed (name, date, scope covered)\n* Record of any anomalies or inappropriate activity identified during the review, with follow-up/remediation evidence\n* List of in-scope privileged/extended-rights accounts at the time of review, to confirm completeness of coverage", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\n \n -Is a review of activities performed with IT privileged accesses conducted and documented for GxP, SOX and CSRD digital solutions?", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": 12}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('8d6aa297-eae8-4d9c-9d2f-ac8bdc1bcf25', 'CREATED', 'CONTROL_DEFINITION', 'f2308fb9-0d05-49a8-b973-5d0d86d41d62', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "B&R-01_SIC", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('d2926d8c-0772-410b-bede-c965194cef7d', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'e0518d71-c843-463b-90a0-9b40e602f6d8', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "DEPLOY", "itProcess": "MANAGE_CONTINUITY", "objective": "Digital solutions must have backup implemented (scheduled, executed and monitored) to meet business needs.", "ownerTeam": "CYBER_SECURITY", "statement": "Backup implementation", "triggerRule": {"groups": [{"conditions": [{"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["EXTERNALLY_MANAGED_PLATFORM"], "operator": "IN", "outcomeKey": "PLATFORM_HOSTING"}]}, {"conditions": [{"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["LIKE_EXTERNAL"], "operator": "IN", "outcomeKey": "PLATFORM_TYPE"}]}, {"conditions": [{"values": ["WEBSITE"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["FULLY_MANAGED"], "operator": "IN", "outcomeKey": "PLATFORM_TYPE"}]}]}, "definitionId": "f2308fb9-0d05-49a8-b973-5d0d86d41d62", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "DFC-QU-SOP-0086073-Backup and Restore - Infrastructure: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/477883", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "Backup requirements describing all the components to be backed up with the required SLA documented and implemented with effective monitoring in place.", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\n\nBack-up set up:\n- Is backup specification documented for the digital solution using the backup specification template?\n- Is the backup configured?\n\nMonitoring and logs:\n- Is the backup monitoring effective and are failures captured?\n- Are the logs traceable and retained for ≥ 6 months?\n\n- For digital solution hosted externally, are back up requirements covered in the contractual clauses with the Third Party?", "autoAttestationRule": {"outcomeKey": "PLATFORM_TYPE", "acceptedValues": ["FULLY_MANAGED"]}, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('fbf8631f-2a0f-4ef8-b284-2a60ee5e924e', 'CREATED', 'CONTROL_DEFINITION', 'f9cc9033-3fd4-4f94-bd70-4e584e88df36', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "BC-01", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('6b35bafe-9840-4d51-9e5a-e5054d865123', 'CREATED', 'CONTROL_DEFINITION_VERSION', '1600ef22-4b77-4d83-a88a-45a7491ce478', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_CONTINUITY", "objective": "A business continuity management process must be defined (e.g., Business Continuity Plan) at business process level with adequate measures established and tested (including Disaster Recovery strategy activation if applicable) to ensure business operations during digital solution’s unavailability (e.g., disasters). This process must be maintained and regularly reviewed to ensure its effectiveness and accuracy.", "ownerTeam": "CYBER_SECURITY", "statement": "Business Continuity", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "f9cc9033-3fd4-4f94-bd70-4e584e88df36", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "1. DIG-CO-SOP-0018146-System Life Cycle: https://opella-connect.veevavault.com/ui/#permalink=V190000000IO009\n2. QUA-CO-OPE-0093984-Business Continuity Plan for GxP Computerized Systems: https://opella-connect.veevavault.com/ui/#permalink=V190000000EQ023", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "Actionable business continuity plan describing how the business activities will be executed in case of digital solution''s unavailability.", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\n\n* Is a Business Continuity Plan (BCP) defined at the business process level for this digital solution?\n* Does the BCP describe adequate measure to sustain business activities during the solutions'' unavailability (e.g. manual workarounds, alternate processes)?\n* For applicable solutions: does the BCP include Disaster Recovery strategy activation steps?\n* Is the BCP reviewed and updated on a regular cadence to ensure it remains accurate and effective (e.g. after solution changes, org changes, or prior test findings)?\n* Is the BCP readily accessible to the people who would need to execute it during an actual disruption?\n* Any digital solution without a maintained, tested BCP - or with a BCP that hasn''t been reviewed within its required cycle - should be treated as non-complaint.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('c200fcef-b212-4f2f-b167-71fb925f012b', 'CREATED', 'CONTROL_DEFINITION', '7dc4ee96-7e85-4926-ac74-093e861e1e91', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "BC-02", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('c308da9d-d71c-41dd-995b-ea9ad2702aaa', 'CREATED', 'CONTROL_DEFINITION_VERSION', '00e30d6c-e04f-4262-aee9-c27677830fd3', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_CONTINUITY", "objective": "Ensure business continuity can be maintained when the digital solution becomes unavailable.", "ownerTeam": "CYBER_SECURITY", "statement": "Alternate Procedures and Continuity Measures", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "7dc4ee96-7e85-4926-ac74-093e861e1e91", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "DIG-CO-OPE-0293533-Corporate Digital Service Continuity and Disaster Recovery Standard\nSECU-CO-MAN-0000101-Business Continuity Management Policy", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "Documented alternate procedures\nBusiness Continuity Plan\nWork instructions\nTraining material\nExercise or test results\nEvidence of periodic review and update\nCorrective actions arising from continuity exercises", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\n\nDocumentation\nAre alternative procedures documented for the affected business activities?\nAre the procedures sufficiently detailed for users to execute them without relying on undocumented knowledge?\nAre roles and responsibilities clearly defined?\nAvailability\nAre the documented procedures available to the personnel who would need to execute them during a disruption?\nCan the procedures be accessed if the digital solution is unavailable?\nTraining\nHave relevant personnel been trained on the alternative procedures?\nIs training evidence available?\nTesting\nHave the alternative procedures been exercised, tested, or used in practice?\nWere the exercises documented?\nWere lessons learned captured?\nMaintenance\nHave the procedures been reviewed within the defined review cycle?\nHave changes in processes, systems, suppliers, or organization been reflected in the procedures?\nEffectiveness\nWould the alternative procedures allow the business activity to continue for the expected disruption period?\nAre there significant manual dependencies or bottlenecks that could prevent successful execution?\nWere any issues identified during testing remediated and tracked to closure?\n\nNon-Compliance Indicators\n\nThe control should be considered non-compliant when:\n\nNo alternative procedure exists.\nProcedures are undocumented.\nProcedures have never been tested.\nPersonnel are unaware of the procedures.\nProcedures are outdated or no longer applicable.\nSignificant deficiencies identified during testing remain unresolved.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('bdfe4884-3766-4abb-ab6d-9b03a1763623', 'CREATED', 'CONTROL_DEFINITION', '4d4a38e3-fa6b-422f-bc9f-390ebdbcf35a', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "RES-01", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('de6368d8-19a2-4468-8b00-3717dc4959e5', 'CREATED', 'CONTROL_DEFINITION', 'aadf54bf-ce93-4cef-a933-a537b4ec4475', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "SEC-04", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('797638d6-8d2e-4650-9f8f-893bbe29e769', 'CREATED', 'CONTROL_DEFINITION_VERSION', '96c211cc-e278-46ec-aa7d-bf3091a64c2c', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_CONTINUITY", "objective": "Vital digital solutions shall demonstrate through testing and documented evidence that recovery can be completed within the approved Recovery Time Objective.", "ownerTeam": "CYBER_SECURITY", "statement": "Recovery Time Objective Demonstration", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "4d4a38e3-fa6b-422f-bc9f-390ebdbcf35a", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "DIG-CO-OPE-0293533-Corporate Digital Service Continuity and Disaster Recovery Standard\nSECU-CO-MAN-0000101-Business Continuity Management Policy", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "Recovery exercise\nRecovery exercise report\nRecovery timings documented: Start time, End time, Measured RTO\nData recovery validated\nDeviations documented and remediated", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\nRecovery Performance\nHas recovery been timed?\nWas recovery completed within the approved RTO (Platinum RTO ≤2; Gold RTO ≤ 4 hours)?\nWas the approved RPO achieved (≤ 15 mins)?\nWere all critical services, data and integrations restored?\nWere all critical services restored?", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('18a199ce-c652-4f51-b745-0bb619b7425a', 'CREATED', 'CONTROL_DEFINITION', 'a257e011-685a-4d4e-807a-b9660a1f1ccb', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "RES-02", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('c529d2cd-0dff-4bb8-a444-1d865dff3e4c', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'f2d53822-da64-4e4a-8d2b-7b4d01f952e0', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_CONTINUITY", "objective": "Dependencies required for recovery shall be identified, documented, and included in recovery procedures and testing activities.", "ownerTeam": "CYBER_SECURITY", "statement": "Critical Dependency Identification and Recovery Sequencing", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "a257e011-685a-4d4e-807a-b9660a1f1ccb", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "DIG-CO-OPE-0293533-Corporate Digital Service Continuity and Disaster Recovery Standard\nSECU-CO-MAN-0000101-Business Continuity Management Policy", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "Dependency map\nRecovery sequence\nArchitecture documentation", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\n\nDependency Identification\nHave all business, technical, infrastructure, security, data, identity, network, integration, and third-party dependencies required for operation and recovery of the digital solution been identified?\nAre dependencies documented in architecture diagrams, recovery procedures, or dependency inventories?\nDoes the dependency inventory include both internal and external services?\nSingle Points of Failure\nHave potential single points of failure been identified and assessed?\nHave mitigation measures been implemented, documented, or formally accepted through risk management processes?\nRecovery Sequence\nIs the recovery sequence documented?\nDoes the recovery sequence identify which systems, services, databases, integrations, and infrastructure components must be recovered first?\nIs the recovery order consistent with the documented recovery procedures?\nRecovery Objectives\nAre dependency recovery objectives aligned with the digital solution''s Recovery Time Objective (RTO) and Recovery Point Objective (RPO)?\nCould any dependency prevent achievement of the approved recovery objectives?\nThird-Party Dependencies\nFor externally provided services, are supplier recovery responsibilities documented?\nHas the supplier demonstrated recovery capability through testing, assurance reports, or contractual commitments?\nEvidence Quality\nIs there evidence that dependency information has been reviewed and updated following significant architecture, supplier, or infrastructure changes?\nNon-Compliance Indicators\n\nThe control should be considered non-compliant if:\n\nCritical dependencies are unknown or undocumented.\nRecovery sequencing is not defined.\nDependency recovery objectives exceed the solution''s approved RTO or RPO.\nSingle points of failure have not been assessed.\nRecovery relies on undocumented supplier capabilities.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('be1da6d2-43ff-464f-a92f-e52a183f6626', 'CREATED', 'CONTROL_DEFINITION', 'c0651225-796d-4f52-acef-35b612021a4c', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "RES-03", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('51aa33a3-bcb2-46d5-a5c0-c48f5640b60f', 'CREATED', 'CONTROL_DEFINITION_VERSION', '659bf5a1-515d-4d9c-9282-8e5a36793836', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_CONTINUITY", "objective": "Ensure recovery objectives and recovery capabilities are defined, implemented, tested, and aligned with the assigned Recovery Tier and Business Criticality classification of the digital solution.", "ownerTeam": "CYBER_SECURITY", "statement": "Vital Application Recovery Readiness Review", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "c0651225-796d-4f52-acef-35b612021a4c", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "DIG-CO-OPE-0293533-Corporate Digital Service Continuity and Disaster Recovery Standard\nSECU-CO-MAN-0000101-Business Continuity Management Policy", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "Annual review report\nAction tracking\nUpdated DR documentation", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\nRecovery Asset Protection\nAre recovery assets identified and documented?\nDo recovery assets include backups, configurations, infrastructure definitions, application components, scripts, documentation, recovery credentials, and recovery environments where applicable?\nAre recovery assets protected from unauthorized modification or deletion?\nRecovery Environment\nIs a recovery environment available and documented?\nCan recovery activities be executed independently from a compromised production environment?\nAre recovery procedures clearly documented?\nRecovery Credentials\nAre recovery accounts and credentials protected and managed appropriately?\nCan recovery activities still be performed if production privileged accounts are unavailable or compromised?\nRecovery Integrity\nAre processes defined to verify the integrity and validity of recovered systems, data, and configurations?\nDoes the recovery process include validation activities before restored services are returned to operation?\nTesting and Validation\nHas the recovery design been tested?\nDo test results demonstrate successful recovery of the required components?\nWere recovery issues identified during testing tracked and remediated?\nRecovery Objective Achievement\nDoes available evidence demonstrate that the cyber recovery design can support the approved Recovery Time Objective (RTO) and Recovery Point Objective (RPO)?\nFor Vital applications, does the design demonstrate capability to support Platinum recovery requirements?\nThird-Party Recovery\nFor externally hosted or supplier-supported solutions, has evidence been reviewed demonstrating the supplier''s ability to support recovery requirements?\nAre responsibilities clearly documented through a Shared Responsibility Model?\n\nCompliance Indicators\nPass\nRecovery Tier assigned.\nRTO and RPO defined.\nRecovery capability documented.\nRecovery capability tested or validated.\nNo material open recovery gaps.\n\nConditional Pass\nRecovery capability exists.\nMinor documentation, testing, or remediation gaps remain.\nDefined action plan exists.\n\nFail\nRecovery Tier not assigned.\nRecovery objectives undefined.\nRecovery capability not documented.\nNo evidence of recovery validation.\nMaterial recovery gaps remain unmanaged.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": 12}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('ffaeac52-5d48-4db1-8940-18db1de6eac9', 'CREATED', 'CONTROL_DEFINITION', '896dbe91-9947-4483-9466-6951740e9331', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "RES-04", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('9f9a7ffd-6b06-4ca0-9862-d283000c649a', 'CREATED', 'CONTROL_DEFINITION_VERSION', '6737d66b-9eeb-4fb6-8e57-b436e5081bf7', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_CONTINUITY", "objective": "Ensure the digital solution can demonstrably recover within approved recovery objectives and that recovery capabilities remain effective throughout the solution lifecycle.", "ownerTeam": "CYBER_SECURITY", "statement": "Recovery Objective Validation", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "896dbe91-9947-4483-9466-6951740e9331", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "DIG-CO-OPE-0293533-Corporate Digital Service Continuity and Disaster Recovery Standard\nSECU-CO-MAN-0000101-Business Continuity Management Policy", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "Recovery test reports\nDisaster Recovery exercise reports\nMeasured recovery duration\nMeasured data recovery point\nRecovery validation evidence\nRecovery improvement actions\nTest result approvals\nSupplier recovery testing evidence (where applicable)", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\n\nRecovery Testing\nHas a recovery exercise been performed?\nWas the recovery exercise completed using documented recovery procedures?\nWas the exercise representative of the recovery scenario being evaluated?\nRecovery Time Objective (RTO)\nWas the actual recovery duration measured?\nDid the digital solution achieve the approved Recovery Time Objective?\nIf the approved RTO was not achieved, was a remediation plan documented?\nRecovery Point Objective (RPO)\nWas the actual data recovery point measured?\nDid the digital solution achieve the approved Recovery Point Objective?\nWas any data loss within the approved tolerance?\nRecovery Scope\nWere all critical solution components recovered?\nWere critical data, configurations, interfaces, integrations, and supporting services included in the recovery validation?\nWere dependencies recovered and operational?\nBusiness Validation\nWas business functionality validated following recovery?\nWere business users involved where appropriate?\nWas the recovered solution demonstrated to be fit for use?\nRemediation and Continuous Improvement\nWere recovery issues, delays, or failures documented?\nWere corrective actions assigned and tracked?\nHas evidence of remediation been reviewed when required?\nThird-Party Recovery\n\nFor supplier-supported solutions:\n\nHas supplier recovery evidence been reviewed?\nHas the supplier demonstrated recovery capability consistent with contractual commitments?\nAre supplier recovery responsibilities clearly documented?\nNon-Compliance Indicators\n\nThis control should be considered non-compliant if:\n\nRecovery exercises have not been performed.\nRecovery objectives cannot be demonstrated.\nRecovery time was not measured.\nRecovery point was not measured.\nRecovery exceeded approved objectives without remediation.\nCritical components were not included in testing.\nRecovery evidence is unavailable.\nSupplier recovery capabilities cannot be demonstrated where applicable.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('b4c2dbb5-cbf6-46c3-8c87-3e478f22e05f', 'CREATED', 'CONTROL_DEFINITION', '82eaaef2-408e-4369-b662-59b3d0489164', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "DP-01", "active": false, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('d9ead4cf-b3c7-4e07-8ff0-c80ffb19d6ca', 'CREATED', 'CONTROL_DEFINITION_VERSION', '215b0c04-0909-4e77-b63a-73446697b8a7', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "PLAN", "itProcess": "MANAGE_RISK", "objective": "The digital solution must undergo a privacy Data Asset Assessment (DAA) to evaluate compliance with privacy requirements.", "ownerTeam": "DATA_PRIVACY_OFFICE", "statement": "Execute Personal Data Privacy Assessment", "triggerRule": {"groups": [{"conditions": [{"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}]}]}, "definitionId": "82eaaef2-408e-4369-b662-59b3d0489164", "reviewerTeam": "DATA_PRIVACY", "sourceOfTruth": "1. EBI-CO-STD-0000410-Opella Data Privacy Standard (v1.0)\nhttps://opella-connect.veevavault.com/ui/#permalink=V190000000KB037\n\n2. Privacy Hub\nhttps://sanofi.sharepoint.com/sites/opella-compliance-site/SitePages/Work-with-personal-data-v1.0.aspx?CT=1736934649051&OR=OWA-NT-Mail&CID=47d9fdb6-098e-ddca-947b-ad4f41eab8f3", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "Personal Data Privacy Assessment documented in OneTrust.", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": true, "attestationGuidance": "1. The digital solution is inventoried as \"digital asset\" in the Opella Privacy Care (One Trust) asset inventory\n2. A Digital Asset Assessment exists and it is either in status \"Completed\" or \"Completed with open risks\"\n3. If the Digital Asset Assessment is \"completed with open risks\", all the risks must be in a status different from \"Ongoing mitigation\" (Avoided, Reduced, Accepted, Expired or Materialized)", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('aae650ea-1c23-4137-a073-dc0ff6ab742c', 'CREATED', 'CONTROL_DEFINITION', 'c72040c9-f3cc-4a2a-83c3-303bf756f0cb', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "DP_RISK-2", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('e5fae6c3-8478-4462-88a9-f3ae3e317718', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'b24a9079-cae3-42d3-89d8-a05b47dee90b', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "PLAN", "itProcess": "MANAGE_RISK", "objective": "The owner of the digital solution must self attest compliance with a list of requirements, depending on the type of the digital solution", "ownerTeam": "DATA_PRIVACY_OFFICE", "statement": "Privacy Compliance Declaration", "triggerRule": null, "definitionId": "c72040c9-f3cc-4a2a-83c3-303bf756f0cb", "reviewerTeam": "DATA_PRIVACY", "sourceOfTruth": "1. EBI-CO-STD-0000410-Opella Data Privacy Standard (v1.0)\nhttps://opella-connect.veevavault.com/ui/#permalink=V190000000KB037\n\n2. Privacy Hub\nhttps://sanofi.sharepoint.com/sites/opella-compliance-site/SitePages/Work-with-personal-data-v1.0.aspx?CT=1736934649051&OR=OWA-NT-Mail&CID=47d9fdb6-098e-ddca-947b-ad4f41eab8f4", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": false, "targetedEvidence": "Privacy Compliance declaration in the risk profiling tool", "applicabilityType": "ALWAYS", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": true, "attestationGuidance": "The owner of the Digital Property must self-attest compliance with certain requirements depending on the digital property type, as a mandatory pre-condition for go-live approval\n\nFor all Digital Solutions, this will be captured in OneTrust when the Digital Assessment is performed.", "autoAttestationRule": null, "assessmentTemplateKey": "DATA_PRIVACY_SELF_ASSESSMENT_V1", "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('37ded8c3-9cf3-41fe-8d83-68a53bccb068', 'CREATED', 'CONTROL_DEFINITION', 'b11d0127-5e35-4680-b5fd-a5c80e7f68ff', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "DEL-02", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('8eee74f7-139e-45f6-b30f-829e4b90b5d5', 'CREATED', 'CONTROL_DEFINITION_VERSION', '56c81f2c-fed5-4268-9b9b-22e28b537280', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "The digital solution must have a defined set of requirements that describe the functional (i.e., business-process related) and non-functional (e.g., Audit Trail, Electronic Record, Electronic Signature, Data Privacy, Cybersecurity) needs to satisfy the business. All requirements must be specific, measurable, achievable, realistic and testable (SMART).", "ownerTeam": "DIGITAL_TECHNOLOGY", "statement": "Gather Requirements", "triggerRule": null, "definitionId": "b11d0127-5e35-4680-b5fd-a5c80e7f68ff", "reviewerTeam": "PRODUCT_PROJECT_DELIVERY", "sourceOfTruth": "DIG-CO-SOP-0018146-System Life Cycle: https://opella-connect.veevavault.com/ui/#permalink=V190000000IO009", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "The requirements the digital solution must meet, including the list of requirements supporting the business process, as well as the applicable non functional requirements.\nE.g.: Epic and user stories in Jira, Requirements in HP ALM, Requirement document in Connect CMS...", "applicabilityType": "ALWAYS", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\n\n* Are both functional (business-process related) and non-functional requirements (e.g. Audit Trail, Electronic Record, Electronic Signature, Data Privacy, Cybersecurity) documented for the digital solution?\n* Is each requirement specific, measurable, achievable, realistic, and testable (SMART)?\n* Are requirements captured and traceable in the appropriate tool for the solution (e.g. Epics/user stories in JIRA, requirements in HP ALM, requirement document in Connect CMS)?\n* Is there evidence requirements were reviewed/approved by the appropriate business and IT stakeholders before design/build began?\n* Are requirements complete relative to the business process being supported, with no material gaps identified later in the lifecycle?\n* Any digital solution where requirements are missing, non-SMART, or not traceable to a recognized system of record should be treated as noncompliant", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('6844a792-d1da-40e3-9613-5558ac033ab5', 'CREATED', 'CONTROL_DEFINITION', 'cd195fb7-8862-43c3-bcdc-24e1bd3ee273', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "DEL-10", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('df8c6621-c886-483b-9323-4f06c4accd7e', 'CREATED', 'CONTROL_DEFINITION_VERSION', '5f57ec26-f758-49a1-aeca-e6c01df3e08a', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "The digital solution must have traceability by linking requirements to its specifications and testing artifacts.", "ownerTeam": "DIGITAL_TECHNOLOGY", "statement": "Ensure Traceability", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "cd195fb7-8862-43c3-bcdc-24e1bd3ee273", "reviewerTeam": "PRODUCT_PROJECT_DELIVERY", "sourceOfTruth": "DIG-CO-SOP-0018146-System Life Cycle: https://opella-connect.veevavault.com/ui/#permalink=V190000000IO009", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "Matrix demonstrating traceability between the requirements, specifications and tests.", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following: \n\n* Is a traceability matrix in place linking each requirement to its corresponding specification(s)?\n* Does the matrix also link each requirement/specification to its corresponding test artifact (test case/script)?\n* Is coverage complete - i.e. can every requirement be traced through to a specification and a test, with no orphaned requirements or untested specifications?\n* Is the traceability matrix kept current as requirements, specifications, or test artifacts change throughout the lifecycle?\n* Can the matrix be used to demonstrate full lifecycle coverage during an audit or inspection (particularly for GxP solutions)?\n* Any digital solution where requirements cannot be traced end-to-end to specifications and tests should be treated as non-compliant.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('ab9c2b01-e6da-4ef0-88a6-9767cdc46c48', 'CREATED', 'CONTROL_DEFINITION', 'ca198329-d0f9-48e0-9178-333aef2713d1', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "DEL-13_SIC", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('f984b429-1006-4ba8-bd35-ab5e20bada77', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'd02723db-9ed4-4e6d-8395-8918b79b58a0', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "DEPLOY", "itProcess": "MANAGE_DELIVERY", "objective": "A summary of controls execution (as per the defined control strategy) must be documented to authorize the usage of the digital solution. Deviations from the controls strategy must be justified. For unresolved deviations, actions plans must be recorded to monitor their resolutions until closure.", "ownerTeam": "DIGITAL_TECHNOLOGY", "statement": "Authorize for Use", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "ca198329-d0f9-48e0-9178-333aef2713d1", "reviewerTeam": "PRODUCT_PROJECT_DELIVERY", "sourceOfTruth": "DIG-CO-SOP-0018146-System Life Cycle: https://opella-connect.veevavault.com/ui/#permalink=V190000000IO009", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "Summary of the Control/Validation Strategy execution, including at least:\n - all the applicable controls and their achievement''s details\n - deviations from the strategy with associated justification and action plan to remediate them\n- the readiness status of the operational & maintenance processes\n- decision to authorize the usage of the digital solution\nE.g.: Authorization for use, Release report", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\n\n- Has a summary of controls executed been documented?\n- Are all controls defined in the control strategy implemented? If not, are deviations justified?\n- For any unresolved deviations, is there an action plan defined with an assigned owner and due date?\n- Based on their impact, are there any unresolved deviation that would block the authorization for use?\n- Have operational readiness activities been properly executed to ensure the digital solution is ready for operation?\n- Has a comprehensive review of control execution, deviations, and operational readiness been conducted to make an informed decision on authorizing the usage of the digital solution?", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('7504474e-bf29-4c8d-b60c-309d841df868', 'CREATED', 'CONTROL_DEFINITION', 'fceaf96c-55f7-4305-bb71-d7f61713c825', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "DEL-14", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('28add6c4-191a-47e0-8f6c-03dcc730bb7c', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'f09f5f5a-6962-4967-801d-0cbd0ea0e1ef', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "The digital solution identified as digital property must adhere to the Digital Properties process.", "ownerTeam": "DIGITAL_TECHNOLOGY", "statement": "Execute Digital Properties Process", "triggerRule": null, "definitionId": "fceaf96c-55f7-4305-bb71-d7f61713c825", "reviewerTeam": null, "sourceOfTruth": "DFC-QU-GOP-0000613-Life Cycle Management of Digital Properties: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/860315", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": false, "targetedEvidence": "Reference of the digital solution recorded in Digital Property Registry.", "applicabilityType": "ALWAYS", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": true, "attestationGuidance": "Reference of the digital solution recorded in Digital Property Registry.", "autoAttestationRule": {"outcomeKey": "PROPERTY_TYPE", "acceptedValues": ["WEBSITE", "SOCIAL", "MOBILE_APP", "CHATBOT"]}, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
