	('8f4c183b-a17f-4fd4-9efb-eeafe3213ca0', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'f3b2351b-fd27-4d89-9aa2-e9e1badc40d1', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "The AI solution risk assessment shall be documented and approved before deployment.", "ownerTeam": "DIGITAL_DATA", "statement": "AI Risk Assessment", "triggerRule": {"groups": [{"conditions": [{"values": ["AI_LIMITED", "AI_HIGH"], "operator": "IN", "outcomeKey": "AI_RISK_CLASSIFICATION"}]}]}, "definitionId": "671f1d67-96c2-4d24-a07b-0ed688499887", "reviewerTeam": "AI", "sourceOfTruth": "https://sanofi.sharepoint.com/sites/ORAIGovernance/SitePages/OR.AI-Opella%20Responsible%20AI.aspx", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "Completed AI Risk Assessment, approval record", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "Has an AI risk assessment been completed before deployment? Has the solution been classified according to the applicable AI risk categories? Have significant risks, limitations, and mitigation measures been documented? Has the AI risk assessment been reviewed and approved by the appropriate stakeholders?", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
