	('76e74d00-1ce1-4e7f-a872-3bcd78285b7e', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'c9bb3a1d-a6d1-4e2a-a23e-8d9b511007ce', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "The AI solution shall have documented intended purpose, architecture, limitations, risks and usage instructions.", "ownerTeam": "DIGITAL_DATA", "statement": "AI Documentation", "triggerRule": {"groups": [{"conditions": [{"values": ["AI_LIMITED", "AI_HIGH"], "operator": "IN", "outcomeKey": "AI_RISK_CLASSIFICATION"}]}]}, "definitionId": "62b9c4fe-3506-4ea3-bfcc-f82495a6da00", "reviewerTeam": "AI", "sourceOfTruth": "https://sanofi.sharepoint.com/sites/ORAIGovernance/SitePages/OR.AI-Opella%20Responsible%20AI.aspx", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "AI Solution Documentation, Architecture Diagram", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "Is the intended purpose of the AI solution documented? Are the architecture, AI models, data sources, knowledge sources, and integrations documented? Are the known limitations, assumptions, and risks documented? Are user instructions and operating procedures available? Is documentation maintained throughout the solution lifecycle?", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
