	('232650b0-c976-48eb-8a72-c889f942d463', 'CREATED', 'CONTROL_DEFINITION_VERSION', '4a264431-0b0f-492c-a80c-2a2ab55426e8', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "Human oversight mechanisms shall be documented and implemented when required by the AI risk classification.", "ownerTeam": "DIGITAL_DATA", "statement": "AI Human Oversight Design", "triggerRule": {"groups": [{"conditions": [{"values": ["AI_HIGH"], "operator": "IN", "outcomeKey": "AI_RISK_CLASSIFICATION"}]}]}, "definitionId": "3152ad42-2e9e-4435-b7a4-e6dfe653ad57", "reviewerTeam": "AI", "sourceOfTruth": "https://sanofi.sharepoint.com/sites/ORAIGovernance/SitePages/OR.AI-Opella%20Responsible%20AI.aspx", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "Design Documentation, User Procedures", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "Are human oversight mechanisms defined and documented? Can users intervene, challenge, approve, or override AI outputs when required? Are roles and responsibilities for oversight clearly defined? Is evidence of human approval or review retained where applicable?", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('d156cf3f-147e-42f9-920a-253c80de42b7', 'CREATED', 'CONTROL_DEFINITION', '631e3947-386f-4144-97cd-9ffe220a1387', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "QUAL-01", "active": false, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('3c5ac0bd-baa9-48a2-8e7f-d2963470b63f', 'CREATED', 'CONTROL_DEFINITION', 'f389d049-52ba-4cd9-a1f4-17616cf00b9c', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "SUP-01", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('a5f644fb-c8d3-41c9-8b55-2946bd199f8e', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'ed2b64e1-814f-4ebf-ad7a-92c790278757', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "RUN", "itProcess": "MANAGE_QUALITY", "objective": "Records generated throughout the digital solution lifecycle (e.g Specifications, Access Request records etc) must be maintained and retained as per the Opella Record Retention Schedule that defines the retention period.", "ownerTeam": "DIGITAL_QUALITY", "statement": "Records Retention", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "631e3947-386f-4144-97cd-9ffe220a1387", "reviewerTeam": "QUALITY", "sourceOfTruth": "DFC-QU-GOP-0000296-Project & System Lifecycle: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/484176", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "*Inventory/list of records generated throughout the digital solution lifecycle (e.g Specifications, Access Request records, test evidence, CRs, etc)\n*Record retention log or archive index mapping each record type to its defined retention period per the Opella Record Retention Schedule\n*Evidence records are stored in a manner that ensures they remain accessible and legible for their full retention period\n* Disposal/destruction record for any documents reaching end of retention, showing this was executed per the schedule (not ad hoc)", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\n\n* Have all record types generated throughout the digital solution lifecycle been identified and mapped to the Opella Record Retention Schedule?\n* Are records actually being retained for the period defined in the schedule (not shorter and not definitely without justification)?\n* Are records stored in a format/location that keeps them accessible and legible throughout the retention period?\n* Where retention periods have lapsed, was disposal handled per the defined process (not informal deletion)?\n* Any record type missing a defined retention period, or retained/disposed of outside the schedule, should be treated as non-compliant.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": 12}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('e746d088-14f4-485b-b42b-a053590b722b', 'CREATED', 'CONTROL_DEFINITION', '934a289e-fa24-491f-a69c-33a9bd6f15ca', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "QUAL-02", "active": false, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('5dea1821-39a5-4e24-8dda-04b612e7489c', 'CREATED', 'CONTROL_DEFINITION_VERSION', '9653efb8-5963-48b3-b289-5f90ac59569a', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "RUN", "itProcess": "MANAGE_QUALITY", "objective": "Detected or potential GxP-related compliance failures impacting a digital solution must be reported as a Quality Event. Each event must be assessed with respect to GxP/Regulatory compliance, Product impact, and Safety, Patients, Data reliability. The associated action plans supporting resolution must be tracked as Corrective Actions and/or Preventive Actions (CAPAs).\n \nNote: For Quality Events reported as non-significant deviations, a Corrective Action and/or Preventive Action is not required.", "ownerTeam": "DIGITAL_QUALITY", "statement": "Deviation", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "934a289e-fa24-491f-a69c-33a9bd6f15ca", "reviewerTeam": "QUALITY", "sourceOfTruth": "1. GQCMS-QU-GOP-0000518-Management of Deviations in QualiPSO: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/741670\n2. GQCMS-QU-GOP-0000286-Escalation of Quality Events and Management of Quality Alerts: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/470603\n3. GQCMS-QU-GOP-0000595-Corrective Action, Preventive Action and Effectiveness Check Management: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/856185", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "* Quality Event record documenting the detected or potential GxP-related compliance failure\n* Assessment documentation covering GxP/Regulatory compliance impact, Product impact, and Safety/Patients/Data reliability impact\n* For significant deviations: CAPA record(s) tracking the associated action plan through to resolution\n*For on-significant deviations: documented rationale confirming CAPA was correctly determined not required\n* Escalation record, where the Quality Event required escalation per the Management of Quality Alerts process", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\n\n* Was the GxP-related compliance failure reported as a Quality Event in a timely manner?\n* Was the event assessed against all required dimensions - GxP/Regulatory compliance, Product impact, and Safety/Patients/Data reliability?\n* For deviations assessed as significant: was a CAPA created and tracked to resolution?\n* For deviations assessed as non-significant: is the \"CAPA not required\" determination documented and justified, not just assumed?\n* Was escalation triggered where the event met escalation criteria?\n* Any GxP-related compliance failure not reported as a Quality Event, or missing a documented significance assessment, should be treated as non-compliant.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": 12}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('999dbc70-c48b-4995-b0ef-da633195cf01', 'CREATED', 'CONTROL_DEFINITION', '547738b3-49f3-4941-9c64-54cb23e30d43', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "QUAL-03", "active": false, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('b0223c48-3861-4751-bc61-667c6e8cef02', 'CREATED', 'CONTROL_DEFINITION_VERSION', '902ec779-ab75-485d-b649-6d514db8ac6f', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "RUN", "itProcess": "MANAGE_QUALITY", "objective": "The remediation of detected or potential failures of a digital  solution to comply with applicable regulatory (e.g. GxP, SOX, CSRD) or Opella requirements  must be tracked and monitored until completion to ensure timely and committed resolution.", "ownerTeam": "DIGITAL_QUALITY", "statement": "Corrective Action Preventive Action", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "547738b3-49f3-4941-9c64-54cb23e30d43", "reviewerTeam": "QUALITY", "sourceOfTruth": "QUA-CO-SOP-0010049-Management of CAPA and Effectiveness:", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "* CAPA record(s) tracking remediation of detected/potential failures against applicable regulatory requirements (GxP, SOX, CSRD) or Opella requirements\n* Action plan with defined owner, due date, and remediation steps\n* Status tracking evidence showing CAPA progress until completion (not just opened and left open)\n* Effectiveness check record confirming the corrective/preventive action actually resolved the underlying issue\n* Escalation or overdue - CAPA report, where applicable, showing timely resolution was monitored", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\n\n* Is every CAPA arising from a detected or potential failure tracked with an assigned owner and due date?\n* Is CAPA status monitored and updated until formal completion/closure?\n* Was an effectiveness check performed to confirm the corrective/preventive action resolved the root cause (not just closed administratively)?\n* Are overdue CAPAs identified and escalated per the defined process?\n* Any CAPA left open past its due date without escalation, or closed without an effectiveness check, should be treated as non-compliant.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": 12}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('416341dc-29b5-4226-8a4e-4538c4cfb637', 'CREATED', 'CONTROL_DEFINITION', 'ae3a6c15-1b7c-4d72-bbba-5e1b3b8e53c1', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "RISK-03", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('aca3c27c-f587-4b1e-a7bd-fc2907521498', 'CREATED', 'CONTROL_DEFINITION_VERSION', '3d295ff0-b3e5-4db4-b6dd-96a4e7415a8a', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "AI models, prompts, grounding data and configurations shall be controlled and versioned.", "ownerTeam": "DIGITAL_DATA", "statement": "AI Model and Prompt Governance", "triggerRule": {"groups": [{"conditions": [{"values": ["AI_LIMITED", "AI_HIGH"], "operator": "IN", "outcomeKey": "AI_RISK_CLASSIFICATION"}]}]}, "definitionId": "a04d45ba-b9de-4cde-8d4b-94ae4811fb6f", "reviewerTeam": "AI", "sourceOfTruth": "https://sanofi.sharepoint.com/sites/ORAIGovernance/SitePages/OR.AI-Opella%20Responsible%20AI.aspx", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "Version History, Configuration Repository", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "Are AI models, prompts, configurations, and knowledge sources version controlled? Are changes documented and approved?  Is a history of modifications maintained? Can previously deployed versions be identified and retrieved?", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('3a5ba697-8d1b-4ed9-a273-4c85b765e418', 'CREATED', 'CONTROL_DEFINITION_VERSION', '17e76564-9562-4b8e-aed7-16129a084476', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_RISK", "objective": "The digital solution''s functions or components must be assessed for potential risks to business, patient safety, product quality, data integrity, and regulatory compliance in the event of a failure. The assessment determines the depth of expected tests or verifications to ensure these risks are controlled.", "ownerTeam": "CYBER_SECURITY", "statement": "Assess Functional Risk", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "ae3a6c15-1b7c-4d72-bbba-5e1b3b8e53c1", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "1. DIG-CO-SOP-0018146-System Life Cycle: https://opella-connect.veevavault.com/ui/#permalink=V190000000IO009", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "The risk assessment of the digital solution''s functionalities or components, describing the impact in case of failure and level of testing or verification required.\nE.g.: Risk issue in JIRA, Risk record in HP ALM, Functional Risk Assessment in Connect CMS...).", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following: \n\n* Has a risk assessment been performed for the digital solution''s functionalities or components, describing the impact in case of failure?\n* Does the assessment determine the appropriate level of testing or verification required based on the identified risk?\n* Is the risk assessment recorded in the appropriate tool for the solution (eg. Risk issue in Jira, Risk record in HP ALM, Functional Risk Assessment in Connect CMS)?\n* Does the assessment cover all functionalities/components in scope, with no material gaps?\n* Is there evidence the resulting testing/verification level was actually applied downstream (eg. traceable to the test strategy)?\n* Any functionality or component without a documented functional risk assessment, or where the assigned testing rigor doesn''t match the assessed risk, should be treated as non-compliant.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('67f923a5-0db4-48de-838c-67d35e58d100', 'CREATED', 'CONTROL_DEFINITION', '061c96c5-db3b-4596-aa25-f41385f13b6d', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "SEC-01", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('de4c079d-5306-43eb-8717-debbd5be4d82', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'a4fec0f0-75a8-40d2-8e0e-9012146b0fe7', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_SECURITY", "objective": "Threats must be identified so that risky scenarios can be understood and mitigated.", "ownerTeam": "CYBER_SECURITY", "statement": "Threat Modeling", "triggerRule": {"groups": [{"conditions": [{"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["OPELLA_MANAGED_PLATFORM"], "operator": "IN", "outcomeKey": "PLATFORM_HOSTING"}]}]}, "definitionId": "061c96c5-db3b-4596-aa25-f41385f13b6d", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "QU-STD-0000469 Secure Development of Applications: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/910529", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "Cybersecurity Threat assessment describing the cyber security risks which can impact the digital solution and the mitigation plan.", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "Create a Security Architecture Review Intake using the form : https://opella-health.atlassian.net/wiki/spaces/CYBSECKB10/pages/557974353/Security+Architecture+Review+Intake", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('b2c8a99b-b868-4f20-ae66-1c71c4907480', 'CREATED', 'CONTROL_DEFINITION', '6ebf73e1-ce36-45d2-93f3-5010e735736f', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "SEC-02_SIC", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('bd8f1e4b-3e94-4333-946b-ee0bebbee977', 'CREATED', 'CONTROL_DEFINITION_VERSION', '023531e8-0471-49c6-8484-fe64a836cd58', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_SECURITY", "objective": "Vulnerabilities at code level of the digital solution must be identified and remediated. Additionally, if open source dependencies within the code are used then they must be reviewed to ensure proper use.", "ownerTeam": "CYBER_SECURITY", "statement": "Cyber Security Code Scan", "triggerRule": {"groups": [{"conditions": [{"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["EXTERNALLY_MANAGED_PLATFORM"], "operator": "IN", "outcomeKey": "PLATFORM_HOSTING"}]}, {"conditions": [{"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["LIKE_EXTERNAL"], "operator": "IN", "outcomeKey": "PLATFORM_TYPE"}]}, {"conditions": [{"values": ["WEBSITE"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["FULLY_MANAGED"], "operator": "IN", "outcomeKey": "PLATFORM_TYPE"}]}]}, "definitionId": "6ebf73e1-ce36-45d2-93f3-5010e735736f", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "QU-STD-0000469 Secure Development of Applications:  https://api-eu.sanofi.com:8443/smartlink/api/qualipso/910529", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "Result of the code scan with list of vulnerabilities detected and indicating that no critical/high vulnerabilities remains open.", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\n\n - Is the code of the digital solution stored into Opella GitHub repository?\n - Has a Cybersecurity code scan been requested and completed, before the release into production, to detect potential vulnerabilities?\n - Is a proof available, including at least: the list of vulnerabilities detected, the scan identifier, the date of the scan, the branch that was scanned, the result of the scan (SCA, SAST...) and name of the person who realized the screenshot and the timestamp?\n - If Critical/High vulnerabilities have been identified, have they been remediated before deployment in Production?\n\nIf open-source code is used:\n - Have we ensured compliance usage with the license terms (e.g. use for commercial purposes allowed, number of workstations allowed)?", "autoAttestationRule": {"outcomeKey": "PLATFORM_TYPE", "acceptedValues": ["FULLY_MANAGED"]}, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
