	('b6e9bc20-996c-4af3-8096-c2e02f417c75', 'CREATED', 'CONTROL_DEFINITION_VERSION', '32e7462f-45a3-4e90-93e3-c7a5fe4dd59f', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_SECURITY", "objective": "Attacks must be simulated to identify overall vulnerabilities before releasing the digital solution to production .", "ownerTeam": "CYBER_SECURITY", "statement": "Cyber Pentest", "triggerRule": {"groups": [{"conditions": [{"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["HIGHLY_CONFIDENTIAL"], "operator": "IN", "outcomeKey": "CONFIDENTIALITY_CLASSIFICATION"}]}]}, "definitionId": "0597a0a7-fa5a-4af9-9114-5f078360f96c", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "DIG-CO-STD-0000031-Systems Security Standard: https://opella-connect.veevavault.com/ui/#permalink=V190000000IV019", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "Cyber pentest report summarizing the simulation of the attacks on the digital solution executed and critical risks remediated.", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "Cyber pentest report summarizing the simulation of the attacks on the digital solution executed and critical risks remediated.", "autoAttestationRule": {"outcomeKey": "PLATFORM_TYPE", "acceptedValues": ["FULLY_MANAGED"]}, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
