	('8fcae420-d99c-4386-a6e6-025972d7d691', 'CREATED', 'CONTROL_DEFINITION_VERSION', '399bf0cb-4612-4ccb-b598-d966c7427b90', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_SECURITY", "objective": "If the digital solution is used in China:\nIt must comply with laws and regulations under China''s cyber security and data security regime.\n\nFor digital solutions hosted outside Mainland China: If No personal information or only Technical Personal data is collected from Mainland China, this control is not applicable. Otherwise a China Cross-Border Data Transfer – Personal Information (CBDT-PI) risk review must be included.\n\nFor digital solutions hosted in Mainland China: this control must be addressed.", "ownerTeam": "CYBER_SECURITY", "statement": "China Digital Compliance Requirement", "triggerRule": {"groups": [{"conditions": [{"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["USED_IN_CHINA"], "operator": "IN", "outcomeKey": "TERRITORIAL_COMPLIANCE_EXTENSION"}]}]}, "definitionId": "35c74124-ad69-4891-9cf2-73f91d91971b", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "QU-GOP-0001332 China Digital Compliance Framework: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/8565258", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "Requestor to contact GRC team - CyberGRC@Opella.com for further instructions", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "Requestor to contact GRC team - CyberGRC@Opella.com for further instructions", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('eb5ebcfa-539d-40d5-94b2-de69106a63ae', 'CREATED', 'CONTROL_DEFINITION', 'd822ebee-5a91-4e81-ba8c-76447f83e11b', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "SEC-07", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('75abf2e2-5887-45cd-a956-debae8e0c6fd', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'beaa32e4-4a66-47d8-8480-ccecd33b657f', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_SECURITY", "objective": "Vulnerabilities of cloud infrastructure code of the digital solution must be identified and remediated.", "ownerTeam": "DIGITAL_TECHNOLOGY", "statement": "Cloud infrastructure code scan", "triggerRule": {"groups": [{"conditions": [{"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["EXTERNALLY_MANAGED_PLATFORM"], "operator": "IN", "outcomeKey": "PLATFORM_HOSTING"}]}]}, "definitionId": "d822ebee-5a91-4e81-ba8c-76447f83e11b", "reviewerTeam": "INFRASTRUCTURE", "sourceOfTruth": "DIG-CO-STD-0000031-Systems Security Standard: https://opella-connect.veevavault.com/ui/#permalink=V190000000IV019", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "PRISMA/ SonarQube code scan report from Github repository indicating that no medium or high vulnerabilities are open.", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "PRISMA/ SonarQube code scan report from Github repository indicating that no medium or high vulnerabilities are open.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('01dd0af5-c0cb-48e9-9617-b64516a82b07', 'CREATED', 'CONTROL_DEFINITION_VERSION', '0949cd7c-1560-48c6-8ffb-31b689442d83', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_SUPPLIER", "objective": "Third Party Risk must be identified during any sourcing activity in order to determine applicable due diligence and contracting actions to be executed prior to final qualification for the Cyber, Data Privacy, and Quality risk domains. A Non-Disclosure Agreement must be signed by both Opella and the 3rd Party to create a confidential relationship if applicable to conduct due diligence activities.", "ownerTeam": "CYBER_SECURITY", "statement": "Identify Third Party Risk", "triggerRule": {"groups": [{"conditions": [{"values": ["THIRD_PARTY_ENGAGED"], "operator": "IN", "outcomeKey": "THIRD_PARTY_ENGAGEMENT"}]}]}, "definitionId": "f389d049-52ba-4cd9-a1f4-17616cf00b9c", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "1. DIG-CO-SOP-0018146-System Life Cycle: https://opella-connect.veevavault.com/ui/#permalink=V190000000IO009\n2. For Quality: DFC-QU-GOP-0000498-CS Third Party Quality Management - Sourcing, Contracting, Management and Termination: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/724974\n3. For Cyber: DIG-CO-STD-0000020-Third Parties - Contractors Cybersecurity requirements: https://opella-connect.veevavault.com/ui/#permalink=V190000000IY025\n4. Procurement Governance: GF-QU-STD-0000419-Procurement Global Operating Standard: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/819585", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "Third Parties risk assessment (e.g Third Party Risk Identification Form completed).", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "All vendors with access to Opella''s network or are critical vendors need to go through the VIRP. During vendor onboarding  in case the vendor does not meet the Opella''s requirements, Risk Acceptance Letter to be signed by the Business", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('e7dcb01b-0e85-4ba4-bf64-10bce020f1d5', 'CREATED', 'CONTROL_DEFINITION', '292626c1-457a-48e4-b8d1-4cdd71021c82', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "SUP-02_SIC", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('582dcd43-090b-42db-a855-59c5a3e08cad', 'CREATED', 'CONTROL_DEFINITION_VERSION', '678a5550-f9bd-4876-b675-338460036b48', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_SUPPLIER", "objective": "According to a risk based approach based on the third party risk identification process,  the Digital Opella contract Owner (the person requesting and managing the contract process) must ensure that Quality contractual Clauses, Cyber Security measures, and Data Privacy Agreements relevant to the scope of services* are included in a contract with the third party.   \n\n*Note : a Contract, including Master Service Agreement can cover services related to one or several digital solutions.", "ownerTeam": "CYBER_SECURITY", "statement": "Contract", "triggerRule": {"groups": [{"conditions": [{"values": ["THIRD_PARTY_ENGAGED"], "operator": "IN", "outcomeKey": "THIRD_PARTY_ENGAGEMENT"}]}]}, "definitionId": "292626c1-457a-48e4-b8d1-4cdd71021c82", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "1. DFC-QU-GOP-0000498-CS Third Party Quality Management - Sourcing, Contracting, Management and Termination: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/724974 \n2. For Cyber: DIG-CO-STD-0000020-Third Parties - Contractors Cybersecurity requirements: https://opella-connect.veevavault.com/ui/#permalink=V190000000IY025", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "Reference of established contract, agreement or Purchase order including proper clauses for each 3rd party used.", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\n\nFor each Third Party providing or supporting the digital solution (SaaS system, On-Premise Software, Middleware, Infrastructure or Platform provider, Managed Services, Outsourced services):\n\n- For Third Party identified as a “High Risk third party”* the control is to be attested in alignment with compliance status found into the High-Risk Third-Party dashboard.\n \nOtherwise:\n \nFor Third Party supporting a GxP  feature / process: \n- Are quality contractual clauses signed by authorized Opella and third party signatories, included into the contract and stored in a contract management system? If not, has a quality contractual clause exemption form been approved by the Contract owner?  \n\n- If the contract is up for renewal by end of the current year, and the contractual clauses have been signed for more than 5 years, is a gap assessment documented and an action plan defined for remediations?\n \nFor Third-Party that either accesses, stores or manages Opella information, has access to Opella systems, or has privileged access, or supports a vital process: Are the Cyber contractual measures included into the contract?\n \nFor Third-Party processing personal data: Is the Data Privacy Agreement included into the contract?\n \n* A High Risk Third Party is a provider supporting either a Vital activity or handling high risk data (highly sensitive data, sensitive personal data or GxP  / SOX relevant data).", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('7ea0e02b-0a70-4ff9-b50c-0b7a1dc57a33', 'CREATED', 'CONTROL_DEFINITION', '71683d28-297d-4101-a40e-4cf7f4d3d942', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "SUP-03_SIC", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('deb9e0b2-7b0a-475f-8a1c-1ed562f1e1cc', 'CREATED', 'CONTROL_DEFINITION_VERSION', '47eb38ee-2766-4d2f-af98-264e19b1b7f7', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_SUPPLIER", "objective": "According to a risk based approach based on the third party risk identification process, an assessment of the 3rd Party is performed in order to evaluate quality, cyber and data privacy compliance. The results of this assessment are documented; it confirms the 3rd party meets Opella requirements to begin providing the solution or service.   \n\nFor SOX digital solutions and associated infrastructure components under the scope of the SOX annual campaign: A yearly independent assessment must be provided for any service outsourced to a Third Party so that compliance assurance is obtained.", "ownerTeam": "CYBER_SECURITY", "statement": "3rd Party Assessments", "triggerRule": {"groups": [{"conditions": [{"values": ["THIRD_PARTY_ENGAGED"], "operator": "IN", "outcomeKey": "THIRD_PARTY_ENGAGEMENT"}]}]}, "definitionId": "71683d28-297d-4101-a40e-4cf7f4d3d942", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "1. DFC-QU-GOP-0000498-CS Third Party Quality Management - Sourcing, Contracting, Management and Termination: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/724974\n2. DFC-QU-GOP-0000204-Computerized Systems Third-Party Assessments: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/351770 \n3. For Cyber: DIG-CO-STD-0000020-Third Parties - Contractors Cybersecurity requirements: https://opella-connect.veevavault.com/ui/#permalink=V190000000IY025", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "Third party Assessments performed including: third party audit/assessment report, Cyber Security certificates evaluation or completed VIRP, Data Privacy assessment.", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\n\nFor each Third Party providing or supporting the digital solution (SaaS system, On-Premise Software, Middleware, Infrastructure or Platform provider, Managed Services, Outsourced services):\n \nFor Third Party identified as a “High Risk third party”*, the control is to be attested in alignment with compliance status found into the High-Risk Third-Party dashboard.\n \nOtherwise, \n \n- For Quality Assessment:\nBased on the Third Party Risk Identification form result for the Third Party, if a Quality Assessment or Quality audit was required, has it been executed and recorded into CONNECT?\n\n- For VIRP (Cyber-Security) Assessment:\nIf the Third-Party either accesses, stores or manage Opella information, has access to Opella systems, or has privileged access, or supports a vital process: Has a VIRP assessment been completed and registered in the CyberVadis tool?\n \n- For Data Privacy Assessment :\nIf the Third Party processes personal data: Has a Data Privacy assessment been performed in OneTrust?\n \n* A High Risk Third Party is a provider supporting either supporting a Vital activity or handling high risk data (highly sensitive data, sensitive personal data or GxP  / SOX relevant data).", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('dad6ab9c-b86d-4008-af7d-cbcee9a739a3', 'CREATED', 'CONTROL_DEFINITION', '93a169aa-e0bb-4285-bb72-ec97fd940a81', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "SUP-04", "active": false, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('ddc103b8-7b6d-401a-98d0-0bf22ff7aaea', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'c7e4ba55-3260-4f7b-b486-35f1c9e97faa', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "RUN", "itProcess": "MANAGE_SUPPLIER", "objective": "Relevant 3rd Party failures potentially impacting the data integrity, security, or privacy aspects associated to the digital solution as well as 3rd Party termination must be reported, assessed and addressed in order to minimize impact and restore controls.", "ownerTeam": "CYBER_SECURITY", "statement": "3rd Party Monitoring and Termination", "triggerRule": {"groups": [{"conditions": [{"values": ["THIRD_PARTY_ENGAGED"], "operator": "IN", "outcomeKey": "THIRD_PARTY_ENGAGEMENT"}]}]}, "definitionId": "93a169aa-e0bb-4285-bb72-ec97fd940a81", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "1. DFC-QU-GOP-0000498-CS Third Party Quality Management - Sourcing, Contracting, Management and Termination: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/724974\n2. DFC-QU-GOP-0000204-Computerized Systems Third-Party Assessments: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/351770\n3. For Cyber: DIG-CO-STD-0000020-Third Parties - Contractors Cybersecurity requirements: https://opella-connect.veevavault.com/ui/#permalink=V190000000IY025", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": true, "targetedEvidence": "* Record of 3rd party failure/incident reported, with impact assessment covering data integrity, security, and privacy aspects\n* Assessment documentation evaluating the failure''s impact on the digital solution and associated controls. \n* Remediation/corrective action record showing how impact was minimized and controls restored\n* For 3rd party termination: documented termination record, including transition/exit plan and confirmation that data handling obligations were met\n* For High Risk Third Parties specifically (supporting Vital activities or handling highly sensitive/GxP/SoX-relevant data): evidence of enhanced monitoring commensurate with that risk classification\n* Reference to the 3rd party''s classification/risk tier, to confirm the correct level of monitoring rigor was applied", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "When attesting this control, consider the following:\n\n* Has the 3rd party''s risk classification (including High Risk status, if applicable) been correctly identified per the defined criteria?\n* Were any 3rd party failures impacting data integrity, security, or privacy reported and assessed in a timely manner?\n* Were corrective actions taken to minimize impact and restore affected controls?\n* For terminated 3rd parties: was termination executed per the defined process, with data/access appropriately closed out?\n* For High Risk Third Parties: is there evidence of monitoring proportionate to that elevated risk (e.g. more frequent reviews, deeper assessments)?\n\nAll employees are required to promptly report any vendor-related incidents of which they become aware.to cyber@opella.com.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": 12}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
