	('a009933b-182e-433d-b35c-6d92daa79588', 'CREATED', 'NFR_DEFINITION_VERSION', 'ffba9785-378f-4f35-a82c-1dc09a920915', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "All websites must integrate with analytics technology that at a minimum track:\n•\tNumber of visits\n•\tEngagement\n•\tSessions per users \n•\tSession time", "ownerTeam": "CYBER_SECURITY", "statement": "I want to ensure the website is equipped with tools to accurately measure usage (e.g., visits and page views) and to produce analytics reports for tracking purposes.", "triggerRule": {"groups": [{"conditions": [{"values": ["WEBSITE"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}]}]}, "definitionId": "4bbe661e-d02c-4249-9fec-54a29fb40971", "reviewerTeam": null, "sourceOfTruth": "", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": false, "targetedEvidence": "", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
