	('909b26b2-56d1-4797-a249-1d0ebe9d624e', 'CREATED', 'NFR_DEFINITION_VERSION', '99e1e604-eb22-431f-9dc3-96419711dbe3', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "The solution shall provide mechanisms allowing human review, approval, intervention, or override of AI-generated outputs where required. Human oversight responsibilities shall be documented and assigned. The solution shall prevent autonomous execution of actions requiring human approval. Where applicable, evidence of human review or approval shall be retained for audit purposes.", "ownerTeam": "DIGITAL_DATA", "statement": "The solution shall provide mechanisms enabling human review, approval, intervention, or override of AI outputs where required.", "triggerRule": {"groups": [{"conditions": [{"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["AI_HIGH"], "operator": "IN", "outcomeKey": "AI_RISK_CLASSIFICATION"}]}]}, "definitionId": "22f21cb0-bdf1-4451-8004-f36b14946226", "reviewerTeam": null, "sourceOfTruth": "", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": false, "targetedEvidence": "", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
