	('34e34ed6-9be5-42de-ac67-3e08c47e6f74', 'CREATED', 'NFR_DEFINITION_VERSION', '20e3e371-37ec-46e6-ad2b-2943c4cfc7e0', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "AI-generated content shall be clearly distinguishable from human-generated content. Users shall be informed when content, recommendations, or responses are generated by AI. AI labels shall be preserved when outputs are exchanged with other digital solutions where technically feasible. Labeling mechanisms shall be consistently applied across all user interfaces.", "ownerTeam": "DIGITAL_DATA", "statement": "AI-generated content shall be clearly distinguishable from human-generated content.", "triggerRule": {"groups": [{"conditions": [{"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["AI_LIMITED", "AI_HIGH"], "operator": "IN", "outcomeKey": "AI_RISK_CLASSIFICATION"}]}]}, "definitionId": "390bc212-d549-48c0-870c-bbd1eb9f405d", "reviewerTeam": null, "sourceOfTruth": "", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": false, "targetedEvidence": "", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
