	('d75656b0-68b8-423a-bacc-6b5156ec51df', 'CREATED', 'NFR_DEFINITION_VERSION', '52b43737-0681-451b-b35f-666fb3832049', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "The solution shall maintain traceability of AI model versions, prompts, configurations, knowledge sources, and generated outputs where applicable. Traceability information shall support audit, investigation, troubleshooting, compliance, and model governance activities. Records shall be protected against unauthorized modification and retained according to applicable retention requirements. Traceability information shall be retrievable throughout the AI solution lifecycle.", "ownerTeam": "DIGITAL_DATA", "statement": "The solution shall maintain traceability of AI models, prompts, configurations, knowledge sources, and generated outputs where required to support audit, investigation, troubleshooting, compliance, and lifecycle management activities.", "triggerRule": {"groups": [{"conditions": [{"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["AI_HIGH"], "operator": "IN", "outcomeKey": "AI_RISK_CLASSIFICATION"}]}]}, "definitionId": "d2f9150a-cfff-4138-a917-d25ae2e14ab5", "reviewerTeam": null, "sourceOfTruth": "", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": false, "targetedEvidence": "", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
