	('047080ac-fe2b-44b3-a217-a764fd5ea10e', 'CREATED', 'NFR_DEFINITION_VERSION', 'a7ef6688-abfd-4a22-bc1c-435f7661a0a3', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "1. The Operating Systems of the infrastructure of the digital solution are not obsolete and supported by Opella. \n2. The systems support regular updates through Opella patching solution and are enrolled in Up2date.", "ownerTeam": "CYBER_SECURITY", "statement": "I want to ensure my digital solution''s infrastructure is up to date and can be patched over time to prevent cybersecurity vulnerabilities.", "triggerRule": {"groups": [{"conditions": [{"values": ["WEBSITE"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}]}]}, "definitionId": "f606b097-b34f-429d-930c-dd47c84e36a6", "reviewerTeam": null, "sourceOfTruth": "", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": false, "targetedEvidence": "", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
