	('d768cc33-c772-44d2-b17d-73955918e485', 'CREATED', 'NFR_DEFINITION_VERSION', '8f5605aa-de18-44fb-9e2c-9acf4fd9cb12', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "1. All unnecessary softwares must be removed from the infrastructure. \n2. All softwares running necessary for the solution must be up-to-date. \n3. Software''s agent and application must be patched regularly, at least when a high or critical vulnerability is disclosed.", "ownerTeam": "CYBER_SECURITY", "statement": "I want to ensure my application is robust against cybersecurity vulnerabilities and that a patching strategy can be defined.", "triggerRule": {"groups": [{"conditions": [{"values": ["WEBSITE"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}]}]}, "definitionId": "d3e94438-9295-4fa1-98e8-99d6f6266eb5", "reviewerTeam": null, "sourceOfTruth": "", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": false, "targetedEvidence": "", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
