	('4a37c4d8-156d-492f-927a-843d707fa051', 'CREATED', 'NFR_DEFINITION_VERSION', '083dfa78-1a4a-4b5f-b824-4e50393a6087', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "If the digital solution stores personal data, the digital solution should allow authorized users to search for and extract all data related to a specific data subject. The extract should be available in a common / machine readable format (csv, txt, xml, ...). Any extraction should be logged by the digital solution for audit and compliance purposes.\nThis feature/right will normally be available to admins/super-users, unless such data extraction is already required as a business/functional requirement (in that case, it will be open to authorized standard users)", "ownerTeam": "DATA_PRIVACY_OFFICE", "statement": "I want to ensure that if a personal data portability request is received, we can fulfill it", "triggerRule": {"groups": [{"conditions": [{"values": ["GENERAL_PERSONAL_DATA", "SENSITIVE_PERSONAL_DATA"], "operator": "IN", "outcomeKey": "PERSONAL_DATA_TYPE"}, {"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}]}]}, "definitionId": "43ff616c-41f3-4c2a-9a40-805a1c018655", "reviewerTeam": null, "sourceOfTruth": "", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": false, "targetedEvidence": "", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
