	('45b9a0c7-b9a9-4805-9919-8261bab718dd', 'CREATED', 'NFR_DEFINITION_VERSION', '6d99439b-300c-41a5-8840-56e94c7e7785', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "If the digital solution stores personal data, the digital solution should allow authorized users to rectify / update personal data of a data subject, if that is inaccurate or obsolete in respect to the purpose for which it is processed(*) Any extraction should be logged by the digital solution for audit and compliance purposes.\nThis feature will normally be available to admins/super-users, unless such data extraction is already required as a business/functional requirement (in that case, it will be open to authorized standard users)\n\n(*) therefore, this requirement to not apply to cases in which personal data shall be retained as it was at the time when it was collected or processed (e.g. for audit or regulatory purposes).", "ownerTeam": "DATA_PRIVACY_OFFICE", "statement": "I want to ensure that if a personal data correction request is received, we can fulfill it", "triggerRule": {"groups": [{"conditions": [{"values": ["GENERAL_PERSONAL_DATA", "SENSITIVE_PERSONAL_DATA"], "operator": "IN", "outcomeKey": "PERSONAL_DATA_TYPE"}, {"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}]}]}, "definitionId": "ca2bd521-f1ff-462f-adc3-93f9d00e14e6", "reviewerTeam": null, "sourceOfTruth": "", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": false, "targetedEvidence": "", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('61f0a03c-0ef1-4c5e-8d96-f3f9f0457531', 'CREATED', 'NFR_DEFINITION', '19549fe9-d68d-4b28-bc75-27af3249f772', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "NFR-54", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('ee724224-65bb-4670-a704-37e8dddad877', 'CREATED', 'NFR_DEFINITION_VERSION', 'fbd751cc-41ca-45a1-b125-21c27726b04c', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "If the digital solution stores personal data, the digital solution should allow authorized users to delete/anonymize the personal data of a data subject. \nAny deletion should be logged by the digital solution for audit and compliance purposes.\n\nThis feature will normally be available to admins/super-users, unless such data extraction is already required as a business/functional requirement (in that case, it will be open to authorized standard users).", "ownerTeam": "DATA_PRIVACY_OFFICE", "statement": "I want to ensure that if a personal data erasure request is received, we can fulfill it", "triggerRule": {"groups": [{"conditions": [{"values": ["GENERAL_PERSONAL_DATA", "SENSITIVE_PERSONAL_DATA"], "operator": "IN", "outcomeKey": "PERSONAL_DATA_TYPE"}, {"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}]}]}, "definitionId": "19549fe9-d68d-4b28-bc75-27af3249f772", "reviewerTeam": null, "sourceOfTruth": "", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": false, "targetedEvidence": "", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('6d5ca382-794e-48c2-85c3-5226c2a4dfa9', 'CREATED', 'NFR_DEFINITION', '98389767-e761-473c-80d4-1a054bc581e5', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "NFR-55", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('f285fa7a-b9b4-4c21-b0a7-17a57113e474', 'CREATED', 'NFR_DEFINITION_VERSION', 'ffb80022-5b3e-4a00-a18c-d523bfde9415', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "If the digital solution exchanges personal data with other solutions or otherwise transmits personal data over a digital network:\n1. all personal data must be encrypted when in transit.\n2.  encryption should be in line with approved encryption standards.\n3. the digital solution should verify that the data encryption was successful, and the data remains encrypted in transit.\n4. the digital solution should not allow unencrypted personal data to be transmitted.\n5. the digital solution should provide a report/log confirming that the data encryption process was successful for audit and compliance purposes.", "ownerTeam": "DATA_PRIVACY_OFFICE", "statement": "I want to ensure that all personal data is encrypted in transit so data is protected from unauthorized access and potential breaches.", "triggerRule": {"groups": [{"conditions": [{"values": ["GENERAL_PERSONAL_DATA", "SENSITIVE_PERSONAL_DATA"], "operator": "IN", "outcomeKey": "PERSONAL_DATA_TYPE"}, {"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}]}]}, "definitionId": "98389767-e761-473c-80d4-1a054bc581e5", "reviewerTeam": null, "sourceOfTruth": "", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": false, "targetedEvidence": "", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('2adcf054-0264-4fa9-b45a-bee52aca3585', 'CREATED', 'NFR_DEFINITION', '1de11137-2f52-4068-8aac-eb6c2c8ff023', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "NFR-56", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('527fc4ea-ae88-42ae-8b03-ef41e6cb79ba', 'CREATED', 'NFR_DEFINITION_VERSION', 'acf7668f-46ac-44d1-b52b-4e5f5bfb58c4', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "If the digital solution allows user to certain choices concerning their own personal data, and/or to set certain preferences concerning personal data, the default value of each choice/preference must be the least intrusive.\n\nExamples:\n- users can choose whether to display their full name or only initials to other uses <-- default = initials\n- users can choose whether to share activity logs for product improvement or not <-- default = no\n- users can choose whether to give feedback or not regarding certain features of the application <-- default = no\n- users can choose whether their status (active or inactive) can be visible to other users <-- default = not visible\n- etc.", "ownerTeam": "DATA_PRIVACY_OFFICE", "statement": "I want to ensure that the default configuration or user''s options is the most conservative in terms of privacy, in accordance with the privacy by default principle / obligation", "triggerRule": {"groups": [{"conditions": [{"values": ["GENERAL_PERSONAL_DATA", "SENSITIVE_PERSONAL_DATA"], "operator": "IN", "outcomeKey": "PERSONAL_DATA_TYPE"}, {"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}]}]}, "definitionId": "c25f3226-020a-4a36-be08-59e1fb3e9129", "reviewerTeam": null, "sourceOfTruth": "", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": false, "targetedEvidence": "", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('096f15ae-8928-4200-8703-497c9795af6a', 'CREATED', 'NFR_DEFINITION', '8fd79e73-ab78-4d2f-bf5f-f049d74ef440', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "NFR-61", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('7ebbc27e-c735-4661-a164-c2d112b18fbf', 'CREATED', 'NFR_DEFINITION_VERSION', 'e054201d-d570-41ff-afcb-f4cda89565db', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "If the digital solution stores personal data:\n1. sensitive personal data must be encrypted by the digital solution when at rest.\n2.  encryption should be in line with approved encryption standards.\n3. the digital solution should verify that the encryption was successful, and the data remains encrypted at rest.\n4. the digital solution should not allow unencrypted personal data to be stored.\n5. the digital solution should provide a report/log confirming that the data encryption process was successful for audit and compliance purposes.", "ownerTeam": "DATA_PRIVACY_OFFICE", "statement": "I want to ensure that all sensitive personal data is encrypted at rest so data is further protected from potential breaches.", "triggerRule": {"groups": [{"conditions": [{"values": ["SENSITIVE_PERSONAL_DATA"], "operator": "IN", "outcomeKey": "PERSONAL_DATA_TYPE"}, {"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}]}]}, "definitionId": "1de11137-2f52-4068-8aac-eb6c2c8ff023", "reviewerTeam": null, "sourceOfTruth": "", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": false, "targetedEvidence": "", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('47676f1a-f948-4ec8-959f-ba6f1f7c8584', 'CREATED', 'NFR_DEFINITION', '10da51e0-4e95-46fd-8ee3-e497270d89c0', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "NFR-57", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('64f10ee4-e1ef-4814-a948-8aba4c6dacf3', 'CREATED', 'NFR_DEFINITION_VERSION', 'a7cce457-3883-469f-8297-fb3df303b172', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "If the digital solution stores personal data, the digital solution must include automated or semi-automated procedures to either delete or anonymize personal data when specific conditions (identified by the business owner) are met.\n\n Examples include, but are not limited to:\n- personal data is deleted/anonymized if/when a certain condition is met (e.g. when the data subject withdraws consent)\n- personal data is deleted/anonymized after a fixed period after a certain condition is met (20 years after the end of the employment contract, or 1 year after the data was collected).\nDifferent subsets of personal data may be subject to different rules.\n\nThe digital solution should not allow for endless retention of personal data", "ownerTeam": "DATA_PRIVACY_OFFICE", "statement": "I want to ensure that personal data is not retained for longer than it is necessary to fulfill the purposes for which it is processed within the digital solution", "triggerRule": {"groups": [{"conditions": [{"values": ["GENERAL_PERSONAL_DATA", "SENSITIVE_PERSONAL_DATA"], "operator": "IN", "outcomeKey": "PERSONAL_DATA_TYPE"}, {"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}]}]}, "definitionId": "10da51e0-4e95-46fd-8ee3-e497270d89c0", "reviewerTeam": null, "sourceOfTruth": "", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": false, "targetedEvidence": "", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('ef16a6eb-2113-46f4-85b7-bc9eb0576c92', 'CREATED', 'NFR_DEFINITION', 'a6c4f64c-07e9-459d-8602-15e9b1f8a60d', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "NFR-58", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('bc59ef98-71a7-469c-bd4d-74eb8a74b034', 'CREATED', 'NFR_DEFINITION_VERSION', 'caeb4390-a6f0-4d79-8e6a-781a7670c8d8', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "If the digital solution stores personal data and supports the processing of such data for different purposes, criteria and controls shall be in place to ensure that once a certain purpose is achieved, the relevant personal data remains available for other purposes but:\na) it can no longer be processed for the already achieved purpose(s), and\nb) access is restricted accordingly.\n\nExample: in a payroll system, time and attendance information of the last working period is actively processed to generate the corresponding payslip and transmit information for payment. When this purpose is achieved, such personal data is no longer needed for that purpose (which is achieved) and is archived to fulfil other purposes, such as to comply with regulatory requirements and allow for audits. As such, the time and attendance information of a certain month shal be retained but it must be frozen (no changes possible), and access should be restricted to those who may need access for regulatory or audit purpose. When all the purposes are achieved, personal data must be deleted or anonymized (see the previous NFR).\n\nExample: user data is processed to allow for login, and for activity tracking. When the user is terminated, the personal data of the user does no longer allow access to the system, but the data is retained for a longer period, for security and audit purpose.", "ownerTeam": "DATA_PRIVACY_OFFICE", "statement": "I want to ensure that personal data is not used and/or accessed when it is no longer needed for certain purposes and to certain users, but remains available to other users and for different purposes (if applicable)", "triggerRule": {"groups": [{"conditions": [{"values": ["GENERAL_PERSONAL_DATA", "SENSITIVE_PERSONAL_DATA"], "operator": "IN", "outcomeKey": "PERSONAL_DATA_TYPE"}, {"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}]}]}, "definitionId": "a6c4f64c-07e9-459d-8602-15e9b1f8a60d", "reviewerTeam": null, "sourceOfTruth": "", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": false, "targetedEvidence": "", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('77337754-a1c0-402e-baab-a580aa98ad6f', 'CREATED', 'NFR_DEFINITION', '9a5352ae-3764-4c1b-84e4-daa4981ef554', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "NFR-59", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('272d5e44-e882-4eb5-aae3-d53046dd5c6b', 'CREATED', 'NFR_DEFINITION_VERSION', '0b77508d-ffe9-4a89-8f6c-4b992bdb6a90', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "If the digital solution includes the possibility to extract/export reports including personal data, such reports shall:\n- include a footer/header disclaimer such as \"This report contains personal data. Handle carefully to prevent unauthorized or unnecessary disclosure and dispose of it when no longer necessary\"\n- includes the name of the user that exported/downloaded the report, and the timestamp.", "ownerTeam": "DATA_PRIVACY_OFFICE", "statement": "I want to facilitate responsible handling of reports including personal data by means of labelling", "triggerRule": {"groups": [{"conditions": [{"values": ["GENERAL_PERSONAL_DATA", "SENSITIVE_PERSONAL_DATA"], "operator": "IN", "outcomeKey": "PERSONAL_DATA_TYPE"}, {"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}]}]}, "definitionId": "9a5352ae-3764-4c1b-84e4-daa4981ef554", "reviewerTeam": null, "sourceOfTruth": "", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": false, "targetedEvidence": "", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('1b35b798-6836-4131-ab13-9db48c990aa7', 'CREATED', 'NFR_DEFINITION_VERSION', '1b04d578-ff6a-47ff-b15c-579b0b436247', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "If the digital solution allows users to input personal data about them, an appropriate privacy notice must be available to users and must be accessible from the digital solution itself  (contact the Privacy Office to get support with regards to identification or drafting of the notice)", "ownerTeam": "DATA_PRIVACY_OFFICE", "statement": "I want to ensure that users are provided with appropriate information concerning the intended use of their data, as required by the law", "triggerRule": {"groups": [{"conditions": [{"values": ["GENERAL_PERSONAL_DATA", "SENSITIVE_PERSONAL_DATA"], "operator": "IN", "outcomeKey": "PERSONAL_DATA_TYPE"}]}]}, "definitionId": "8fd79e73-ab78-4d2f-bf5f-f049d74ef440", "reviewerTeam": null, "sourceOfTruth": "", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": false, "targetedEvidence": "", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('aa7e76e1-c484-4132-be29-804d02632067', 'CREATED', 'NFR_DEFINITION', '7c099805-9cd2-47b9-861f-d1717413d7f4', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "NFR-62", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('93eef719-48e3-4de6-b6d7-3822d1367649', 'CREATED', 'NFR_DEFINITION_VERSION', '04304e77-12eb-4011-918a-417e24fb67fc', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "Ensure that access to personal data and related functions of the digital solution is restricted to authorized users based on defined roles and legitimate business needs. Access shall be governed by a formal authorization process and implemented through appropriate authentication mechanisms, role-based access controls, and least-privilege principles. Access rights shall be appropriately provisioned, periodically reviewed, modified, and revoked throughout the user lifecycle.", "ownerTeam": "DATA_PRIVACY_OFFICE", "statement": "I want to ensure that data is not exposed to users who don''t really need it, as this would constitute a data breach.", "triggerRule": {"groups": [{"conditions": [{"values": ["GENERAL_PERSONAL_DATA", "SENSITIVE_PERSONAL_DATA"], "operator": "IN", "outcomeKey": "PERSONAL_DATA_TYPE"}]}]}, "definitionId": "7c099805-9cd2-47b9-861f-d1717413d7f4", "reviewerTeam": null, "sourceOfTruth": "", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt", "evidenceRequired": false, "targetedEvidence": "", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "requiredForGoLive": false, "attestationGuidance": "", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
	('2645011b-aca1-4ee2-a9ef-e978bacbd0c7', 'CREATED', 'NFR_DEFINITION', 'd02054d0-2fce-4c75-9138-0c67c875785a', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', NULL, NULL, '{"after": {"code": "NFR-63", "active": true, "createdByUserId": "k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt"}, "before": null}', '2026-10-23 10:31:20.621', 'USER'),
