-- Generated catalogue-only data. Apply after Prisma migrations and admin bootstrap.
BEGIN;
DO $dpr_catalogue$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM "user" AS u
    INNER JOIN user_role AS ur ON ur.user_id = u.id
    WHERE u.id = 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt' AND ur.role = 'DPR_ADMIN'
  ) THEN
    RAISE EXCEPTION 'Catalogue actor % is not an existing DPR Admin', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt';
  END IF;

  IF EXISTS (SELECT 1 FROM region)
     OR EXISTS (SELECT 1 FROM country)
     OR EXISTS (SELECT 1 FROM agency)
     OR EXISTS (SELECT 1 FROM brand)
     OR EXISTS (SELECT 1 FROM control_definition)
     OR EXISTS (SELECT 1 FROM nfr_definition)
     OR EXISTS (
       SELECT 1 FROM audit_event
       WHERE entity_type IN (
         'CONTROL_DEFINITION',
         'CONTROL_DEFINITION_VERSION',
         'NFR_DEFINITION',
         'NFR_DEFINITION_VERSION'
       )
     )
  THEN
    RAISE EXCEPTION 'Production catalogue target is not empty';
  END IF;
END
$dpr_catalogue$;

