	('67b865df-1880-4e61-a784-235980bb9730', 'c1c7a1b1-c8fa-407f-bc44-8b0bffecc600', 1, 'RISK_PROFILE_V1', 'INITIAL_IMPORT', 'DIGITAL_DATA', 'MANAGE_DELIVERY', 'BUILD', 'APPROVAL_REQUIRED', 'AI Transparency Assessment', 'AI transparency obligations shall be identified and implemented before deployment.', 'https://sanofi.sharepoint.com/sites/ORAIGovernance/SitePages/OR.AI-Opella%20Responsible%20AI.aspx', 'Transparency Assessment, User Notification Evidence', 'Are users informed when interacting with AI-generated content where required? Are AI-generated outputs clearly distinguishable from human-generated content? Are transparency requirements consistently applied across user interfaces?', 'OUTCOME_TRIGGERED', '{"groups": [{"conditions": [{"values": ["AI_LIMITED", "AI_HIGH"], "operator": "IN", "outcomeKey": "AI_RISK_CLASSIFICATION"}]}]}', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', '2026-10-23 10:31:20.621', '2026-10-23 10:31:20.621', NULL, NULL, 'AI', NULL, true, false),
