	('3d295ff0-b3e5-4db4-b6dd-96a4e7415a8a', 'a04d45ba-b9de-4cde-8d4b-94ae4811fb6f', 1, 'RISK_PROFILE_V1', 'INITIAL_IMPORT', 'DIGITAL_DATA', 'MANAGE_DELIVERY', 'BUILD', 'APPROVAL_REQUIRED', 'AI Model and Prompt Governance', 'AI models, prompts, grounding data and configurations shall be controlled and versioned.', 'https://sanofi.sharepoint.com/sites/ORAIGovernance/SitePages/OR.AI-Opella%20Responsible%20AI.aspx', 'Version History, Configuration Repository', 'Are AI models, prompts, configurations, and knowledge sources version controlled? Are changes documented and approved?  Is a history of modifications maintained? Can previously deployed versions be identified and retrieved?', 'OUTCOME_TRIGGERED', '{"groups": [{"conditions": [{"values": ["AI_LIMITED", "AI_HIGH"], "operator": "IN", "outcomeKey": "AI_RISK_CLASSIFICATION"}]}]}', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', '2026-10-23 10:31:20.621', '2026-10-23 10:31:20.621', NULL, NULL, 'AI', NULL, true, false),
	('7d15c024-38c6-4176-9b55-1e88340882df', '3be9b0b1-f601-4f3e-aeff-36ca6a5dbc68', 1, 'RISK_PROFILE_V1', 'INITIAL_IMPORT', 'DIGITAL_DATA', 'MANAGE_DELIVERY', 'BUILD', 'APPROVAL_REQUIRED', 'AI Explainability Assessment', 'High-risk AI solutions shall include appropriate explainability information for intended users.', 'https://sanofi.sharepoint.com/sites/ORAIGovernance/SitePages/OR.AI-Opella%20Responsible%20AI.aspx', 'Explainability Documentation', 'Is information available to explain how AI outputs are generated? Are explanations appropriate for the intended audience? Are limitations and uncertainties communicated where appropriate? Has explainability information been documented and reviewed?', 'OUTCOME_TRIGGERED', '{"groups": [{"conditions": [{"values": ["AI_HIGH"], "operator": "IN", "outcomeKey": "AI_RISK_CLASSIFICATION"}]}]}', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', '2026-10-23 10:31:20.621', '2026-10-23 10:31:20.621', NULL, NULL, 'AI', NULL, true, false),
	('5f7f8579-4f80-49c5-861f-4bf7255d131d', '919160f6-ef77-49e5-8503-1cc2b33fba99', 1, 'RISK_PROFILE_V1', 'INITIAL_IMPORT', 'DIGITAL_DATA', 'MONITOR_PERFORMANCE_INDICATORS', 'RUN', 'APPROVAL_REQUIRED', 'AI Performance Monitoring', 'AI solutions shall be monitored in production to identify degradation, quality issues or unexpected behaviour.', 'https://sanofi.sharepoint.com/sites/ORAIGovernance/SitePages/OR.AI-Opella%20Responsible%20AI.aspx', 'Monitoring Dashboard, Monitoring Report', 'Is monitoring in place for AI quality, reliability, and performance? Have monitoring metrics and thresholds been defined? Are alerts generated when performance degrades?  Are monitoring results periodically reviewed? Are corrective actions defined and tracked when issues are detected?', 'OUTCOME_TRIGGERED', '{"groups": [{"conditions": [{"values": ["AI_LIMITED", "AI_HIGH"], "operator": "IN", "outcomeKey": "AI_RISK_CLASSIFICATION"}]}]}', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', '2026-10-23 10:31:20.621', '2026-10-23 10:31:20.621', NULL, 12, 'AI', NULL, true, false),
	('4c2b1bc9-da59-4ad5-b566-16a2c585033c', 'c9757b62-a23d-47eb-8601-fbab745dd357', 1, 'RISK_PROFILE_V1', 'INITIAL_IMPORT', 'DIGITAL_DATA', 'MONITOR_PERFORMANCE_INDICATORS', 'RUN', 'APPROVAL_REQUIRED', 'AI Incident Monitoring', 'AI-related incidents shall be recorded, assessed and remediated.', 'https://sanofi.sharepoint.com/sites/ORAIGovernance/SitePages/OR.AI-Opella%20Responsible%20AI.aspx', 'Incident Records', 'Are AI-related incidents recorded and investigated? Are root causes identified and documented?  Are corrective and preventive actions implemented? Are significant incidents escalated appropriately? Are lessons learned incorporated into the AI solution lifecycle?', 'OUTCOME_TRIGGERED', '{"groups": [{"conditions": [{"values": ["AI_HIGH"], "operator": "IN", "outcomeKey": "AI_RISK_CLASSIFICATION"}]}]}', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', '2026-10-23 10:31:20.621', '2026-10-23 10:31:20.621', NULL, 12, 'AI', NULL, true, false),
	('fc3dce27-34d7-47e5-bb4f-f721a2949000', '0e9baadb-bf39-4022-917c-846a5f929e23', 1, 'RISK_PROFILE_V1', 'INITIAL_IMPORT', 'DIGITAL_DATA', 'MONITOR_PERFORMANCE_INDICATORS', 'RUN', 'APPROVAL_REQUIRED', 'AI Continuous Improvement', 'AI solutions shall be periodically reviewed for continued fitness for intended use.', 'https://sanofi.sharepoint.com/sites/ORAIGovernance/SitePages/OR.AI-Opella%20Responsible%20AI.aspx', 'Periodic Review Report, Improvement Actions', 'Is the AI solution periodically reviewed for continued fitness for intended use? Are changes in business requirements, data, or operating context assessed? Are improvement opportunities documented and tracked? Are monitoring results used to drive improvements? Is periodic review evidence retained?', 'OUTCOME_TRIGGERED', '{"groups": [{"conditions": [{"values": ["AI_LIMITED", "AI_HIGH"], "operator": "IN", "outcomeKey": "AI_RISK_CLASSIFICATION"}]}]}', 'k2V7PtwJFVmlaX60WM6U0JDDu7bYD9mt', '2026-10-23 10:31:20.621', '2026-10-23 10:31:20.621', NULL, 12, 'AI', NULL, true, false),
